#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_shape;
uniform float amzp_tile;
uniform float amzp_avgCol;
uniform float amzp_edgeSnap;
uniform float amzp_jitter;
uniform float amzp_animSpd;
uniform float amzp_facet;
uniform float amzp_lines;
layout(color) uniform half4 amzp_lineCol;
uniform float amzp_lineW;
uniform float amzp_blendMode;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_seed;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float TT() { return time; }
    float3 unpre(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    float hsh(float2 p) { float3 p3 = fract(float3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
    float TS;
    float vAt(float2 p) { return luma(unpre(layerClamp(p / layer))); }
    float2 gpt(float x, float y, float T) {
        float rowO = (mod(y, 2.0) - 0.5) * 0.5;
        float2 pt = float2(x + rowO, y);
        float2 pp = pt * TS;
        float e = TS * 0.5;
        float2 g = float2(vAt(pp + float2(e, 0.0)) - vAt(pp - float2(e, 0.0)), vAt(pp + float2(0.0, e)) - vAt(pp - float2(0.0, e)));
        float amzSource_gl = length(g);
        float2 sh = float2(0.0);
        if (amzSource_gl > 0.0001) sh = g / amzSource_gl * clamp(amzSource_gl * 2.5 * amzp_edgeSnap, 0.0, 0.32);
        float2 jr = float2(hsh(pt + amzp_seed), hsh(pt + 9.1 + amzp_seed)) - 0.5;
        float2 ja = float2(sin(T * amzp_animSpd + jr.x * 30.0), cos(T * amzp_animSpd * 0.83 + jr.y * 30.0)) * step(0.0001, amzp_animSpd);
        sh += (jr + ja * 0.5) * amzp_jitter * 0.4;
        return (pt + sh) * TS;
    }
    float crs(float2 a, float2 b) { return a.x * b.y - a.y * b.x; }
    bool inTri(float2 p, float2 a, float2 b, float2 c) {
        float d1 = crs(b - a, p - a), d2 = crs(c - b, p - b), d3 = crs(a - c, p - c);
        bool neg = d1 < 0.0 || d2 < 0.0 || d3 < 0.0;
        bool amzLocal_pos = d1 > 0.0 || d2 > 0.0 || d3 > 0.0;
        return !(neg && amzLocal_pos);
    }
    float segD(float2 p, float2 a, float2 b) { float2 pa = p - a, ba = b - a; float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0); return length(pa - ba * h); }
    float2 cellOf(float2 P, float T, out float de) {
        if (int(amzp_shape) == 1 || int(amzp_shape) == 3) {
            float2 q = int(amzp_shape) == 3 ? rot2(0.78539816) * P : P;
            float2 c = floor(q / TS);
            float2 l = q - c * TS;
            de = min(min(l.x, TS - l.x), min(l.y, TS - l.y));
            float2 cq = (c + 0.5) * TS;
            return int(amzp_shape) == 3 ? rot2(-0.78539816) * cq : cq;
        }
        if (int(amzp_shape) == 2) {
            float2 sv = float2(1.0, 1.7320508);
            float2 p = P / TS;
            float4 hC = floor(float4(p, p - float2(0.5, 1.0)) / sv.xyxy) + 0.5;
            float2 c1 = hC.xy * sv, c2 = (hC.zw + 0.5) * sv;
            float2 c = dot(p - c1, p - c1) < dot(p - c2, p - c2) ? c1 : c2;
            float2 l = abs(p - c);
            float hd = max(dot(l, normalize(sv)), l.x);
            de = max(0.5 - hd, 0.0) * TS;
            return c * TS;
        }
        float2 g = floor(P / TS);
        float f1 = 1e9, f2 = 1e9;
        float2 best = P;
        for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
                float2 id = g + float2(float(i), float(j));
                float2 jr = float2(hsh(id + amzp_seed * 1.37), hsh(id + 7.7 + amzp_seed * 1.37)) - 0.5;
                float2 ja = float2(sin(T * amzp_animSpd + jr.x * 30.0), cos(T * amzp_animSpd * 0.83 + jr.y * 30.0)) * step(0.0001, amzp_animSpd) * 0.25;
                float2 pt = (id + 0.5 + jr * mix(0.6, 0.95, clamp(amzp_jitter, 0.0, 1.0)) + ja) * TS;
                float d = length(P - pt);
                if (d < f1) { f2 = f1; f1 = d; best = pt; } else if (d < f2) f2 = d;
            }
        }
        de = 0.5 * (f2 - f1);
        return best;
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        TS = max(amzp_tile * pxs(), 2.0);
        float T = TT();
        float2 P = amzLayerNorm() * W;
        float4 src = orig;
        float4 mos = src;
        if (int(amzp_shape) != 0) {
            float de = 1e9;
            float2 cen = cellOf(P, T, de);
                    float4 c0 = layerClamp(cen / W);
            float o = TS * 0.25;
            float4 av = (c0 + layerClamp((cen + float2(o, o)) / W) + layerClamp((cen + float2(-o, o)) / W)
                     + layerClamp((cen + float2(o, -o)) / W) + layerClamp((cen + float2(-o, -o)) / W)) / 5.0;
            mos = mix(c0, av, clamp(amzp_avgCol, 0.0, 1.0));
            float3 mc = unpre(mos);
            if (amzp_facet > 0.0) {
                float e = TS * 0.35;
                float2 gr = float2(vAt(cen + float2(e, 0.0)) - vAt(cen - float2(e, 0.0)), vAt(cen + float2(0.0, e)) - vAt(cen - float2(0.0, e)));
                float3 n = normalize(float3(-gr * 1.6, 1.0));
                float lgt = dot(n, normalize(float3(-0.5, 0.6, 0.8)));
                float bev = 1.0 - smoothstep(0.0, TS * 0.18, de);
                mc *= mix(1.0, 0.55 + 0.75 * lgt + 0.25 * bev, clamp(amzp_facet, 0.0, 2.0) * 0.5);
            }
            if ((amzp_lines>0.5)) {
                float lw = amzp_lineW * pxs() * 0.5;
                mc = mix(mc, amzp_lineCol.rgb, 1.0 - smoothstep(lw, lw + 1.0, de));
            }
            mos = float4(clamp(mc * amzp_hardness, 0.0, 1.0) * mos.a, mos.a);
        } else {
        float gy = floor(P.y / TS);
        float2 A = float2(0.0), B = float2(0.0), Cc = float2(0.0);
        bool found = false;
        for (int sy = 0; sy < 3; sy++) {
            float y0 = gy + float(sy == 0 ? 0 : (sy == 1 ? -1 : 1));
            float y1 = y0 + 1.0;
            float o0 = mod(y0, 2.0) - 0.5, o1 = mod(y1, 2.0) - 0.5;
            float k = o0 < o1 ? 0.0 : 1.0;
            float ix = floor(P.x / TS);
            for (int i = -1; i <= 1; i++) {
                float fi = ix + float(i);
                float2 a0 = gpt(fi, y0, T), a1 = gpt(fi + 1.0, y0, T);
                float2 bk = gpt(fi + k, y1, T), bk0 = gpt(fi + k - 1.0, y1, T);
                if (inTri(P, a0, a1, bk)) { A = a0; B = a1; Cc = bk; found = true; break; }
                if (inTri(P, bk0, bk, a0)) { A = bk0; B = bk; Cc = a0; found = true; break; }
            }
            if (found) break;
        }
        if (found) {
            float2 cen = (A + B + Cc) / 3.0;
            mos = layerClamp(cen / W);
            float3 mc = unpre(mos);
            if (amzp_facet > 0.0) {
                float ha = vAt(A), hb = vAt(B), hc = vAt(Cc);
                float3 n = normalize(cross(float3(B - A, (hb - ha) * TS * 0.8), float3(Cc - A, (hc - ha) * TS * 0.8)));
                if (n.z < 0.0) n = -n;
                float lgt = dot(n, normalize(float3(-0.5, 0.6, 0.8)));
                mc *= mix(1.0, 0.55 + 0.75 * lgt, clamp(amzp_facet, 0.0, 2.0) * 0.5);
            }
            if ((amzp_lines>0.5)) {
                float d = min(segD(P, A, B), min(segD(P, B, Cc), segD(P, Cc, A)));
                float lw = amzp_lineW * pxs() * 0.5;
                mc = mix(mc, amzp_lineCol.rgb, 1.0 - smoothstep(lw, lw + 1.0, d));
            }
            mos = float4(clamp(mc * amzp_hardness, 0.0, 1.0) * mos.a, mos.a);
        }
        }
        if (!(amzp_overdrawOn>0.5)) {
            if (mos.a < 0.02) mos = src;
            mos = float4(unpre(mos) * src.a, src.a);
        }
        float4 res;
        float3 sc = unpre(src), mcs = unpre(mos);
        if (int(amzp_blendMode) == 0) res = mos;
        else if (int(amzp_blendMode) == 1) res = mos + src * (1.0 - mos.a);
        else if (int(amzp_blendMode) == 2) res = float4(sc * mcs * src.a, src.a);
        else res = float4((1.0 - (1.0 - sc) * (1.0 - mcs)) * src.a, src.a);
        float4 R = mix(src, res, amzp_alpha);
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
